from __future__ import annotations

import os
import subprocess
from pathlib import Path
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from thirdparty.internal.model.recipe import RecipeBase


def _to_meson_value(value: Any) -> str:
    """Convert a Python value to a meson native-file / -D flag value string."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    # Strings are quoted
    return f"'{value}'"


def _find_vcvarsall() -> str:
    """Return the path to vcvarsall.bat from the latest VS installation."""
    vswhere = r"C:\Program Files (x86)\Microsoft Visual Studio\Installer\vswhere.exe"
    result = subprocess.run(
        [vswhere, "-latest", "-property", "installationPath"],
        capture_output=True, text=True,
    )
    vs_path = result.stdout.strip()
    return os.path.join(vs_path, "VC", "Auxiliary", "Build", "vcvarsall.bat")


def _find_cl_exe() -> str | None:
    """Return the path to the latest cl.exe via vswhere, or None."""
    vswhere = r"C:\Program Files (x86)\Microsoft Visual Studio\Installer\vswhere.exe"
    result = subprocess.run(
        [vswhere, "-latest", "-find", r"VC\Tools\MSVC\**\bin\Hostx64\x64\cl.exe"],
        capture_output=True, text=True,
    )
    for line in reversed(result.stdout.strip().splitlines()):
        p = line.strip()
        if os.path.isfile(p):
            return p
    return None


class MesonToolchain:
    """Generates a Meson native file used by ``Meson.configure()``."""

    _BUILDTYPE_MAP = {
        "Release":      "release",
        "Debug":        "debug",
        "RelWithDebInfo": "debugoptimized",
        "MinSizeRel":   "minsize",
    }

    def __init__(self, recipe: "RecipeBase", backend: str | None = None) -> None:
        self._recipe = recipe
        self._backend: str = backend or "ninja"
        # Set by the recipe in generate() — mirrors Conan's MesonToolchain API
        self.project_options: dict[str, Any] = {}
        self.cpp_args: list[str] = []
        self.c_args: list[str] = []
        self.link_args: list[str] = []

    def generate(self) -> None:
        recipe = self._recipe
        meson_buildtype = self._BUILDTYPE_MAP.get(recipe.build_type, "release")

        lines: list[str] = ["# Generated by ThirdParty MesonToolchain\n\n"]

        # ------------------------------------------------------------------ #
        # [binaries] — tell meson where to find cmake and MSVC compiler      #
        # ------------------------------------------------------------------ #
        lines.append("[binaries]\n")
        lines.append("cmake = 'cmake'\n")
        cl_exe = _find_cl_exe()
        if cl_exe:
            cl_posix = cl_exe.replace("\\", "/")
            lines.append(f"c = '{cl_posix}'\n")
            lines.append(f"cpp = '{cl_posix}'\n")
        lines.append("\n")

        # ------------------------------------------------------------------ #
        # [cmake] — inject CMAKE_PREFIX_PATH so meson cmake-method deps work #
        # ------------------------------------------------------------------ #
        if recipe.dep_package_paths:
            paths = [p.replace("\\", "/") for p in recipe.dep_package_paths]
            paths_repr = "[" + ", ".join(f"'{p}'" for p in paths) + "]"
            lines.append("[cmake]\n")
            lines.append(f"CMAKE_PREFIX_PATH = {paths_repr}\n")
            lines.append("\n")

        # ------------------------------------------------------------------ #
        # [built-in options] — build type, default_library, and flags        #
        # ------------------------------------------------------------------ #
        lines.append("[built-in options]\n")
        lines.append(f"buildtype = '{meson_buildtype}'\n")
        if meson_buildtype == "release":
            lines.append("b_ndebug = 'true'\n")
        lines.append(f"backend = '{self._backend}'\n")
        # Mirror the recipe's shared option as default_library
        _shared = recipe.options.get_safe("shared", True)
        _default_library = "shared" if _shared else "static"
        lines.append(f"default_library = '{_default_library}'\n")
        if self.cpp_args:
            cpp_args_repr = "[" + ", ".join(f"'{a}'" for a in self.cpp_args) + "]"
            lines.append(f"cpp_args = {cpp_args_repr}\n")
        if self.c_args:
            c_args_repr = "[" + ", ".join(f"'{a}'" for a in self.c_args) + "]"
            lines.append(f"c_args = {c_args_repr}\n")
        if self.link_args:
            link_args_repr = "[" + ", ".join(f"'{a}'" for a in self.link_args) + "]"
            lines.append(f"c_link_args = {link_args_repr}\n")
            lines.append(f"cpp_link_args = {link_args_repr}\n")
        lines.append("\n")


        # ------------------------------------------------------------------ #
        # [project options] — per-recipe -D flags                            #
        # ------------------------------------------------------------------ #
        if self.project_options:
            lines.append("[project options]\n")
            for key, value in self.project_options.items():
                lines.append(f"{key} = {_to_meson_value(value)}\n")
            lines.append("\n")

        native_file = Path(recipe.build_folder) / "thirdparty_meson_native.ini"
        native_file.parent.mkdir(parents=True, exist_ok=True)
        native_file.write_text("".join(lines), encoding="utf-8")
        print(f"[thirdparty] MesonToolchain: wrote {native_file}")


class Meson:
    """Wraps ``meson setup``, ``meson compile``, and ``meson install``."""

    def __init__(self, recipe: "RecipeBase") -> None:
        self._recipe = recipe

    def _run(self, cmd: list[str], cwd: str | None = None) -> None:
        """Run a meson command wrapped in the MSVC environment on Windows."""
        vcvarsall = _find_vcvarsall()
        if os.path.isfile(vcvarsall):
            cmd_str = subprocess.list2cmdline(cmd)
            wrapped = f'call "{vcvarsall}" x64 && {cmd_str}'
            subprocess.run(wrapped, cwd=cwd, check=True, shell=True)
        else:
            subprocess.run(cmd, cwd=cwd, check=True)

    def configure(self, source_folder: str | None = None) -> None:
        src = Path(source_folder or self._recipe.source_folder)
        build = Path(self._recipe.build_folder)
        native_file = build / "thirdparty_meson_native.ini"

        cmd: list[str] = ["meson", "setup"]

        # Re-configure if an existing setup is present
        if (build / "build.ninja").exists() or (build / "meson-private").is_dir():
            cmd.append("--reconfigure")

        if native_file.exists():
            cmd += ["--native-file", str(native_file)]

        # Install prefix — always forward slashes
        prefix = self._recipe.package_folder.replace("\\", "/")
        cmd.append(f"--prefix={prefix}")

        cmd += [str(src), str(build)]

        print(f"[thirdparty] {' '.join(cmd)}")
        self._run(cmd)

    def build(self) -> None:
        build = self._recipe.build_folder
        cmd = ["meson", "compile", "-C", str(build)]
        print(f"[thirdparty] {' '.join(cmd)}")
        self._run(cmd)

    def install(self) -> None:
        build = self._recipe.build_folder
        cmd = ["meson", "install", "-C", str(build), "--no-rebuild"]
        print(f"[thirdparty] {' '.join(cmd)}")
        self._run(cmd)
